INSERT INTO _seed_neuro_ap1_context (unit_id,actor_id) SELECT curricular_unit_id,updated_by FROM quiz_topics WHERE id='quiz-topic-neuro-ap1' AND status='published' AND deleted_at IS NULL LIMIT 1;
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-020',unit_id,'quiz-topic-neuro-ap1','Na norma anterior, qual é o principal osso da fronte?',NULL,'Visto anteriormente, o crânio tem geralmente forma ovóide e é mais largo superiormente do que inferiormente. A porção superior é formada pelo <strong>osso frontal</strong>, situado profundamente à região da fronte e superiormente às órbitas. Superomedialmente a cada órbita existe um arco supraciliar arredondado, geralmente mais pronunciado no sexo masculino; entre ambos pode existir uma elevação mediana, a glabela.<p><small>Gray’s Anatomy, 42.ª ed., p. 558.</small></p>','hard','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-020-answer','quiz-neuro-ap1-020','Osso frontal',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-020-incorrect','quiz-neuro-ap1-020','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-021',unit_id,'quiz-topic-neuro-ap1','Que elevação mediana pode existir entre os arcos supraciliares?',NULL,'A porção superior é formada pelo osso frontal, situado profundamente à região da fronte e superiormente às órbitas. Superomedialmente a cada órbita existe um arco supraciliar arredondado, geralmente mais pronunciado no sexo masculino; entre ambos pode existir uma elevação mediana, a <strong>glabela</strong>. A glabela pode apresentar vestígios da sutura interfrontal ou metópica, que geralmente encerra durante o primeiro ano pós-natal, mas persiste numa pequena percentagem de adultos de diferentes populações.<p><small>Gray’s Anatomy, 42.ª ed., p. 558.</small></p>','medium','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-021-answer','quiz-neuro-ap1-021','Glabela',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-021-incorrect','quiz-neuro-ap1-021','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-022',unit_id,'quiz-topic-neuro-ap1','Como se designa a persistência da sutura interfrontal no adulto?',NULL,'A glabela pode apresentar vestígios da sutura interfrontal ou metópica, que geralmente encerra durante o primeiro ano pós-natal, mas persiste numa pequena percentagem de adultos de diferentes populações. Quando persiste, é mais comum na porção inferior da sutura e esta variante designa-se <strong>metopismo</strong>. O frontal articula-se com os dois ossos nasais nas suturas frontonasais, marcadas por uma depressão na raiz do nariz.<p><small>Gray’s Anatomy, 42.ª ed., p. 558.</small></p>','medium','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-022-answer','quiz-neuro-ap1-022','Metopismo',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-022-incorrect','quiz-neuro-ap1-022','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-023',unit_id,'quiz-topic-neuro-ap1','Que suturas unem o frontal aos ossos nasais?',NULL,'Quando persiste, é mais comum na porção inferior da sutura e esta variante designa-se metopismo. O frontal articula-se com os dois ossos nasais nas <strong>suturas frontonasais</strong>, marcadas por uma depressão na raiz do nariz. A porção superior da face é ocupada pelas órbitas e pela ponte nasal.<p><small>Gray’s Anatomy, 42.ª ed., p. 558.</small></p>','medium','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-023-answer','quiz-neuro-ap1-023','Suturas frontonasais',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-023-incorrect','quiz-neuro-ap1-023','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-024',unit_id,'quiz-topic-neuro-ap1','Que osso forma integralmente o bordo supraorbitário?',NULL,'<strong>O bordo supraorbitário é inteiramente formado pelo frontal</strong> e pode ser interrompido, na transição entre os dois terços laterais mais agudos e o terço medial arredondado, pela incisura ou buraco supraorbitário, que transmite o nervo e os vasos supraorbitários.<p><small>Gray’s Anatomy, 42.ª ed., p. 558.</small></p>','hard','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-024-answer','quiz-neuro-ap1-024','Osso frontal',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-024-incorrect','quiz-neuro-ap1-024','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-025',unit_id,'quiz-topic-neuro-ap1','Que estrutura atravessa a incisura supraorbitária?',NULL,'<strong>O bordo supraorbitário é inteiramente formado pelo frontal e pode ser interrompido, na transição entre os dois terços laterais mais agudos e o terço medial arredondado, pela incisura ou buraco supraorbitário, que transmite o nervo e os vasos supraorbitários.</strong> O bordo lateral da órbita é formado principalmente pela apófise frontal do zigomático e é completado superiormente pela apófise zigomática do frontal; entre ambas situa-se a sutura frontozigomática, numa depressão palpável.<p><small>Gray’s Anatomy, 42.ª ed., p. 558.</small></p>','hard','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
