INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-026',unit_id,'quiz-topic-neuro-ap1','Que vasos acompanham o nervo na incisura supraorbitária?',NULL,'O bordo supraorbitário é inteiramente formado pelo frontal e pode ser interrompido, na transição entre os dois terços laterais mais agudos e o terço medial arredondado, pela incisura ou buraco supraorbitário, que transmite o nervo e os <strong>vasos supraorbitários</strong>. O bordo lateral da órbita é formado principalmente pela apófise frontal do zigomático e é completado superiormente pela apófise zigomática do frontal; entre ambas situa-se a sutura frontozigomática, numa depressão palpável.<p><small>Gray’s Anatomy, 42.ª ed., p. 558.</small></p>','hard','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
