INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-027',unit_id,'quiz-topic-neuro-ap1','Que sutura se encontra no bordo lateral da órbita entre frontal e zigomático?',NULL,'O bordo supraorbitário é inteiramente formado pelo frontal e pode ser interrompido, na transição entre os dois terços laterais mais agudos e o terço medial arredondado, pela incisura ou buraco supraorbitário, que transmite o nervo e os vasos supraorbitários. O bordo lateral da órbita é formado principalmente pela apófise frontal do zigomático e é completado superiormente pela apófise zigomática do frontal; entre ambas situa-se a <strong>sutura frontozigomática</strong>, numa depressão palpável. O bordo infraorbitário é formado lateralmente pelo zigomático e medialmente pela maxila.<p><small>Gray’s Anatomy, 42.ª ed., p. 558.</small></p>','hard','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-027-answer','quiz-neuro-ap1-027','Sutura frontozigomática',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-027-incorrect','quiz-neuro-ap1-027','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-028',unit_id,'quiz-topic-neuro-ap1','Que osso forma lateralmente o bordo infraorbitário?',NULL,'O bordo lateral da órbita é formado principalmente pela apófise frontal do <strong>zigomático</strong> e é completado superiormente pela apófise zigomática do frontal; entre ambas situa-se a sutura frontozigomática, numa depressão palpável. O bordo infraorbitário é formado lateralmente pelo zigomático e medialmente pela maxila. Os bordos lateral e infraorbitário são agudos e palpáveis.<p><small>Gray’s Anatomy, 42.ª ed., p. 558.</small></p>','hard','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-028-answer','quiz-neuro-ap1-028','Zigomático',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-028-incorrect','quiz-neuro-ap1-028','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-029',unit_id,'quiz-topic-neuro-ap1','Que osso forma medialmente o bordo infraorbitário?',NULL,'O bordo infraorbitário é formado lateralmente pelo zigomático e <strong>medialmente pela maxila</strong>. Os bordos lateral e infraorbitário são agudos e palpáveis.<p><small>Gray’s Anatomy, 42.ª ed., p. 558.</small></p>','hard','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-029-answer','quiz-neuro-ap1-029','Maxila',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-029-incorrect','quiz-neuro-ap1-029','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-030',unit_id,'quiz-topic-neuro-ap1','Que osso forma superiormente o bordo medial da órbita?',NULL,'Os bordos lateral e infraorbitário são agudos e palpáveis. O bordo medial da órbita é formado superiormente pelo <strong>frontal</strong> e inferiormente pela crista lacrimal da apófise frontal da maxila.<p><small>Gray’s Anatomy, 42.ª ed., p. 558.</small></p>','hard','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
